BEGIN READ ONLY; SET LOCAL statement_timeout = '10s'; SELECT set_config('request.jwt.claims', '{"role":"authenticated"}', true); SET LOCAL ROLE authenticated;SELECT jsonb_build_object('role',current_user,'auth_uid_is_null',auth.uid() IS NULL,'eligible_shops',(SELECT count(*) FROM public.sync_staff_shop_ids()),'visible_sync_rows',(SELECT count(*) FROM public.sync_records),'pull_ok',public.sync_pull(0,1,NULL)->'ok','pull_records',jsonb_array_length(public.sync_pull(0,1,NULL)->'records')) AS result; ROLLBACK;
